int soil_sensor_read(struct soil_data_s *data)
{
  uint8_t resp[MODBUS_RESP_SIZE + 4];
  static bool s_not_init_warned;
  int ret;

  if (g_fd < 0)
    {
      if (!s_not_init_warned)
        {
          printf("[SOIL] Not initialized (read skipped)\n");
          s_not_init_warned = true;
