   * 是两个任务共享同一 fd —— 不加锁会互相抢收发字节导致双双超时。 */
  pthread_mutex_lock(&g_uart_lock);

  /* 丢弃上次残留字节（超时/异常后 FIFO 里可能还有脏数据） */
  tcflush(g_fd, TCIFLUSH);

  if (soil_sensor_send_command(g_fd) < 0)
    {
      printf("[SOIL] send failed (errno=%d)\n", errno);
      pthread_mutex_unlock(&g_uart_lock);
      return -1;
    }

  ret = soil_sensor_receive_response(g_fd, resp, sizeof(resp));
  if (ret < 0)
    {
      printf("[SOIL] recv failed/timeout\n");
      pthread_mutex_unlock(&g_uart_lock);
      return -1;
    }

  soil_sensor_parse_data(resp, data);
  pthread_mutex_unlock(&g_uart_lock);
  return 0;
}
