static void sensor_cloud_upload(void)
{
#ifdef CONFIG_PLANT_AI_MODULE
  struct sensor_view_s v;
  char json[256];

  if (!server_bridge_configured())
    {
      return;
    }

  sensor_service_get_view(&v);
  if (!v.valid)
    {
      return;   /* 传感器不在/读取失败：不上报，保持手机 "--" */
    }

  snprintf(json, sizeof(json),
           "{\"moisture\":%.1f,\"temp\":%.1f,\"ec\":%.1f,"
           "\"salt\":%.2f,\"n\":%.1f,\"p\":%.1f,\"k\":%.1f,\"ph\":%.1f,"
           "\"source\":\"board\"}",
           v.moisture, v.temp, v.ec, v.salt, v.nitrogen,
           v.phosphorus, v.potassium, v.ph);

  if (server_bridge_post_json("sensor", json) == 0)
    {
      printf("[SOIL] 上云 OK moisture=%.1f%%\n", v.moisture);
    }
#else
  (void)0;
#endif
}

