void screen_data_refresh(const struct sensor_view_s *view,
                         const struct sensor_history_s *hist)
{
  char buf[24];

  if (view == NULL)
    {
      return;
    }

  if (s_moisture_val != NULL && s_moisture_note != NULL)
    {
      snprintf(buf, sizeof(buf), "%.0f%%", view->moisture);
      lv_label_set_text(s_moisture_val, buf);
      lv_label_set_text(s_moisture_note, view->moisture_note);
      lv_obj_set_style_bg_color(s_moisture_dot, status_color(view->moisture_status), 0);
    }

  if (s_temp_val != NULL && s_temp_note != NULL)
    {
      snprintf(buf, sizeof(buf), "%.0f°c", view->temp);
      lv_label_set_text(s_temp_val, buf);
      lv_label_set_text(s_temp_note, view->temp_note);
      lv_obj_set_style_bg_color(s_temp_dot, status_color(view->temp_status), 0);
    }

  if (s_light_val != NULL && s_light_note != NULL)
    {
      lv_label_set_text(s_light_val,
                        view->light_status == 2 ? "充足" :
                        (view->light_status == 1 ? "中等" : "有点暗"));
      lv_label_set_text(s_light_note, "光照");
      lv_obj_set_style_bg_color(s_light_dot, status_color(view->light_status), 0);
    }

  if (s_ec_val != NULL && s_ec_note != NULL)
    {
      snprintf(buf, sizeof(buf), "%.1f", view->ec / 1000.0f);
      lv_label_set_text(s_ec_val, buf);
      lv_label_set_text(s_ec_note, view->ec_note);
      lv_obj_set_style_bg_color(s_ec_dot, status_color(view->ec_status), 0);
    }

  /* 趋势图：7 天水分 */

  if (s_chart != NULL && s_chart_ser != NULL && hist != NULL)
    {
      int i;

      for (i = 0; i < SENSOR_HISTORY_DAYS; i++)
        {
          if (hist->valid[i])
            {
              s_chart_ser->y_points[i] = (int32_t)hist->moisture[i];
            }
          else
            {
              s_chart_ser->y_points[i] = 0;
            }
        }

      lv_chart_refresh(s_chart);
    }
}

