static void cam_on_delete(lv_event_t *e)
{
  (void)e;

#ifdef CONFIG_PLANT_CAMERA_CAPTURE
  camera_preview_stop();

  s_ai_pending = false;
  s_ai_result[0] = '\0';
  s_cam_stopped = false;
  s_cam_busy = false;

  /* 延迟启动定时器未触发就销毁页面 → 一并删除，防悬垂回调 */

  if (s_start_timer != NULL)
    {
      lv_timer_delete(s_start_timer);
      s_start_timer = NULL;
    }

  if (s_frame_timer != NULL)
    {
      lv_timer_delete(s_frame_timer);
      s_frame_timer = NULL;
    }

  s_frame_label = NULL;
#endif
}

#ifdef CONFIG_PLANT_CAMERA_CAPTURE
/* ⚠️ 2026-09-09：预览延迟启动回调（一次性定时器，150ms）。
 * 直接 camera_preview_start 会在 LVGL 首帧渲染前就直写 LCD（先出摄像头
 * 图像、后画界面 → 观感怪）。延迟到页面渲染完成后启动，UI 先就位。 */

static void preview_start_delayed_cb(lv_timer_t *timer)
{
  (void)timer;

  s_start_timer = NULL;
  if (!s_cam_stopped && !s_cam_busy)
    {
      camera_preview_start(CAM_VIEW_X, CAM_VIEW_Y,
                           CAM_VIEW_W, CAM_VIEW_H);
    }
}
#endif /* CONFIG_PLANT_CAMERA_CAPTURE */

#ifdef CONFIG_PLANT_CAMERA_CAPTURE
/* LVGL 定时器：ui_task 上下文刷新右上角帧计数（只失效标签自身小区域，
 * 不碰取景框内部；同时证明预览线程活着）。
 * 附带职责：拍照冻结（take）后，从诊断页返回本页（可见）时自动恢复
 * 实时预览 —— 冻结必须在页面隐藏期间保持（否则线程直写会撕坏盖在
 * 上层的诊断页内容）。 */

static void frame_timer_cb(lv_timer_t *timer)
{
  (void)timer;

#ifdef CONFIG_PLANT_CAMERA_CAPTURE
  /* 手机相机式预览（直写 LCD，= plant cam preview 的逻辑）：
   * 后台线程 capture → lcd_put_rgb565 直写取景框内部；无 LVGL 对象
   * 与之竞争，无 lv_image 渲染 bug。 */

  if (camera_init() == 0)
    {
      if (!s_cam_configured)
        {
          if (camera_config_rgb565_qvga() == 0)
            {
              /* 首次配置含 1s AEC/AWB 收敛等待 */
              s_cam_configured = true;
            }
        }

      /* ⚠️ 2026-09-09：延迟 150ms 启动预览（等 LVGL 本页首帧渲染完成，
       * 避免"先出摄像头图、后画界面"的怪观感；销毁时定时器一并清理） */

      if (s_start_timer == NULL)
        {
          s_start_timer = lv_timer_create(preview_start_delayed_cb, 150, NULL);
          lv_timer_set_repeat_count(s_start_timer, 1);
        }

      /* 帧计数（调试辅助）：右上角小字，只失效自身区域 */

      s_frame_label = lv_label_create(scr);
      lv_label_set_text(s_frame_label, "帧 0");
      lv_obj_set_style_text_font(s_frame_label, TP_FONT_BODY, 0);
      lv_obj_set_style_text_color(s_frame_label, lv_color_hex(0x475569), 0);
      lv_obj_align(s_frame_label, LV_ALIGN_TOP_RIGHT, -12, 40);

      if (s_frame_timer == NULL)
        {
          s_frame_timer = lv_timer_create(frame_timer_cb, 500, NULL);
        }
    }
#endif

  /* 页面销毁（返回）时停止预览线程 */

  lv_obj_add_event_cb(scr, cam_on_delete, LV_EVENT_DELETE, NULL);

  return scr;
}

